SELECT * FROM torn_stock_portfolio_annual_settlement
WHERE portfolio_code = #{portfolioCode}
  AND settle_year = #{settleYear}
  AND rule_version = #{ruleVersion}
  AND deleted = 0

SELECT * FROM torn_stock_portfolio_annual_settlement
WHERE portfolio_code = #{portfolioCode}
  AND rule_version = #{ruleVersion}
  AND settlement_status = 'SETTLED'
  AND settle_year < #{settleYear}
  AND deleted = 0
ORDER BY settle_year DESC
LIMIT 1

